def store_review_posts_to_comments(apps, schema_editor):
    """
    お店の口コミは、お店のページのコメントとして持つ (専用のページは作らない)。
    投稿 (Post) として書かれたお店の口コミを、お店へのコメントに移す。
    スタンプ・付いていたコメント (→ 返信)・お知らせ・日時・写真もそのまま移す。
    """

    Comment = apps.get_model("washoku", "Comment")
    CommentReaction = apps.get_model("washoku", "CommentReaction")
    Notification = apps.get_model("washoku", "Notification")
    Post = apps.get_model("washoku", "Post")
    PostReaction = apps.get_model("washoku", "PostReaction")

    for post in Post.objects.filter(kind="product", store__isnull=False).order_by("pk"):

        comment = Comment.objects.create(
            store_id=post.store_id,
            author_id=post.author_id,
            kind="tip",
            body=post.body,
            verdict=post.verdict,
            photo_url=post.photo_1 or "",
            is_hidden=post.status != "published",
            admin_checked=True,
        )
        Comment.objects.filter(pk=comment.pk).update(created_at=post.created_at)

        Comment.objects.filter(post=post, parent__isnull=True).update(post=None, store_id=post.store_id, parent=comment)
        Comment.objects.filter(post=post).update(post=None, store_id=post.store_id)

        for reaction in PostReaction.objects.filter(post=post):
            CommentReaction.objects.get_or_create(comment=comment, user_id=reaction.user_id, kind=reaction.kind)

        Notification.objects.filter(post=post).update(post=None, comment=comment)

        post.delete()


